from pydantic import BaseModel
import json
from fastapi.testclient import TestClient

class ModelA(BaseModel):
    a: str

class ModelB(BaseModel):
    b: str

app = FastAPI(
    responses={
        500: {
            'model': ModelA | ModelB,
            'content': {"application/json": {
                'examples': {"Case A": {"value": "a"}}
            }}
        }
    }
)

@app.get('/route1')
def route1():
    return "test"

@app.get('/route2')
def route2():
    return "test"

